#include <iostream>
using namespace std;

int puissance(int base, int exposant = 2) {
    int resultat = 1;
    for (int i = 0; i < exposant; ++i)
        resultat = resultat * base;
    return resultat;
}

int main() {
    cout << puissance(5) << endl;
    cout << puissance(2, 5) << endl;
    cout << puissance(3, 0) << endl;
    return 0;
}

