solution.referenceCode:
#include <iostream>
using namespace std;

int maximum(int a, int b) {
    if (a > b)
        return a;
    else
        return b;
}

int maximum(int a, int b, int c) {
    return maximum(maximum(a, b), c);
}

int main() {
    int x, y, z;
    cin >> x >> y >> z;
    cout << maximum(x, y) << endl;
    cout << maximum(x, y, z) << endl;
    return 0;
}

