#include <iostream>
using namespace std;

class CompteBancaire {
    private:
        double solde;
    public:
        CompteBancaire(double depot) : solde(depot) {}
        void deposer(double montant) { solde = solde + montant; }
        void retirer(double montant) {
            if (montant <= solde)
                solde = solde - montant;
        }
        double getSolde() { return solde; }
};

int main() {
    CompteBancaire c(100);
    c.deposer(50);
    c.retirer(200);
    c.retirer(30);
    cout << c.getSolde() << endl;
    return 0;
}

